set -e
S="$TEMP/logscan-scratch"; mkdir -p "$S/bench/tests"
{
  echo "// Differential test: original tokenizer (module old) vs the refactored logscan::tokenize."
  echo "use logscan::{tokenize, LexError, Token};"
  echo ""
  echo "#[allow(dead_code)]"
  echo "mod old {"
  echo "use logscan::{LexError, Token};"
  # original file minus its own `use` line and its Token enum (lines 1-16), so it shares logscan::Token
  sed -n '17,$p' "$S/orig_token.rs"
  echo "}"
  cat <<'EOF'

fn check(line: &str) {
    let new: Vec<Result<Token<'_>, LexError>> = tokenize(line).collect();
    let old: Vec<Result<Token<'_>, LexError>> = old::tokenize(line).collect();
    assert_eq!(new, old, "diverged on {line:?}");
}

#[test]
fn every_line_up_to_length_seven_matches_the_original() {
    let alpha = [b'a', b'=', b'"', b'\\', b'[', b']', b' ', b'\t', b'n'];
    let mut checked = 0u64;
    for len in 0..=7u32 {
        for mut code in 0..alpha.len().pow(len) {
            let mut bytes = Vec::with_capacity(len as usize);
            for _ in 0..len {
                bytes.push(alpha[code % alpha.len()]);
                code /= alpha.len();
            }
            check(std::str::from_utf8(&bytes).unwrap());
            checked += 1;
        }
    }
    eprintln!("exhaustive lines checked: {checked}");
}

#[test]
fn random_longer_lines_with_multibyte_text_match_the_original() {
    let alpha: Vec<&str> = vec![
        "a", "x", "=", "\"", "\\", "[", "]", " ", "\t", "n", "t", "\\\"", "é", "ü", "%", "0", "\r", "=\"", "] ",
    ];
    let mut s: u64 = 0x2545F4914F6CDD1D;
    let mut next = move || {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        s
    };
    let mut checked = 0u64;
    for _ in 0..300_000 {
        let len = (next() % 40) as usize;
        let mut line = String::new();
        for _ in 0..len {
            line.push_str(alpha[(next() % alpha.len() as u64) as usize]);
        }
        check(&line);
        checked += 1;
    }
    eprintln!("random lines checked: {checked}");
}
EOF
} > "$S/bench/tests/diff.rs"
cd "$S/bench" && cargo test --release --test diff -- --nocapture 2>&1 | tail -25

