                    return Some(Ok(Token::Bare(&src[p..p])));
                }
                if b[p] == b'"' {
                    let s = p + 1;
                    let mut i = s;
                    loop {
                        if i >= n {
                            self.st = 2;
                            self.pos = n;
                            return Some(Err(LexError::UnterminatedQuote { pos: p }));
                        }
                        match b[i] {
                            b'"' => break,
                            b'\\' => {
                                if i + 1 >= n {
                                    self.st = 2;
                                    self.pos = n;
                                    return Some(Err(LexError::UnterminatedQuote { pos: p }));
                                }
                                match b[i + 1] {
                                    b'"' | b'\\' | b'n' | b't' | b'r' => i += 2,
                                    _ => {
                                        self.st = 2;
                                        self.pos = n;
                                        return Some(Err(LexError::InvalidEscape { pos: i }));
                                    }
                                }
                            }
                            _ => i += 1,
                        }
                    }
                    if i + 1 < n && b[i + 1] != b' ' && b[i + 1] != b'\t' {
                        self.st = 2;
                        self.pos = n;
                        return Some(Err(LexError::ExpectedSeparator { pos: i + 1 }));
                    }
                    self.st = 0;
                    self.pos = i + 1;
                    Some(Ok(Token::Quoted(&src[s..i])))
                } else {
                    let mut i = p;
                    while i < n && b[i] != b' ' && b[i] != b'\t' {
                        if b[i] == b'"' {
                            self.st = 2;
                            self.pos = n;
                            return Some(Err(LexError::UnexpectedQuote { pos: i }));
                        }
                        i += 1;
                    }
                    self.st = 0;
                    self.pos = i;
                    Some(Ok(Token::Bare(&src[p..i])))
                }
            }
            _ => None,
        }
    }
}
}

fn check(line: &str) {
    let new: Vec<Result<Token<'_>, LexError>> = tokenize(line).collect();
    let old: Vec<Result<Token<'_>, LexError>> = old::tokenize(line).collect();
    assert_eq!(new, old, "diverged on {line:?}");
}

#[test]
fn every_line_up_to_length_seven_matches_the_original() {
    let alpha = [b'a', b'=', b'"', 0x5c, b'[', b']', b' ', b'\t', b'n'];
    let mut checked = 0u64;
    for len in 0..=7u32 {
        for mut code in 0..alpha.len().pow(len) {
            let mut bytes = Vec::with_capacity(len as usize);
            for _ in 0..len {
                bytes.push(alpha[code % alpha.len()]);
                code /= alpha.len();
            }
            check(std::str::from_utf8(&bytes).unwrap());
            checked += 1;
        }
    }
    eprintln!("exhaustive lines checked: {checked}");
}

#[test]
fn random_longer_lines_with_multibyte_text_match_the_original() {
    let alpha: Vec<&str> = vec![
        "a", "x", "=", "\"", "\\", "[", "]", " ", "\t", "n", "t", "r", "\\\"", "é", "ü", "%", "0", "\r", "=\"", "] ",
    ];
    let mut s: u64 = 0x2545F4914F6CDD1D;
    let mut next = move || {
        s ^= s << 13;
        s ^= s >> 7;
        s ^= s << 17;
        s
    };
    let mut checked = 0u64;
    for _ in 0..300_000 {
        let len = (next() % 40) as usize;
        let mut line = String::new();
        for _ in 0..len {
            line.push_str(alpha[(next() % alpha.len() as u64) as usize]);
        }
        check(&line);
        checked += 1;
    }
    eprintln!("random lines checked: {checked}");
}

