        match rnd() % 10 {
            0 => l.push_str(&format!("msg=\"disk {}% full \\\"x\\\" \\n\" ", i % 100)),
            1 => l.push_str("retries= "),
            2 => l.push_str(&format!("{} ", words[(rnd() % 5) as usize])),
            3 => l.push_str("a=\"bad\\q\" "),          // error path
            4 => l.push_str("x\"y=1 "),                // error path
            5 => l.push_str("path=/var/log\tdone "),   // tab separator
            _ => l.push_str(&format!("k{}=v{} ", rnd() % 50, rnd() % 1000)),
        }
        if i % 13 == 0 { l.push_str("[broken"); }
        lines.push(l);
    }
    lines
}

fn main() {
    let lines = corpus();
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    let mut best = f64::MAX;
    let mut out = Stats::default();
    for _ in 0..9 {
        let t = Instant::now();
        let mut stats = Stats::default();
        for line in &lines {
            stats.add_line(black_box(line));
        }
        out = black_box(stats);
        best = best.min(t.elapsed().as_secs_f64());
    }
    println!("{:?} | {:.1} MB | best {:.1} ms | {:.0} MB/s",
        (out.timestamps, out.pairs, out.words, out.rejected_lines), bytes as f64 / 1e6, best * 1e3, bytes as f64 / 1e6 / best);
}
EOF
for v in old new; do cp "$S/main_stats.rs" "$S/bench_$v/src/main.rs"; (cd "$S/bench_$v" && cargo build --release -q); done
for i in $(seq 1 6); do
  "$S/bench_new/target/release/bench.exe" | sed 's/^/new /'
  "$S/bench_old/target/release/bench.exe" | sed 's/^/old /'
done | awk '{for(i=1;i<=NF;i++) if($i=="best"){v=$(i+1); if(!($1 in m) || v<m[$1]) m[$1]=v; s[$1]+=v; n[$1]++}} END{for(k in m) printf "%s: min %.1f ms, mean %.1f ms over %d runs\n", k, m[k], s[k]/n[k], n[k]}'
"$S/bench_new/target/release/bench.exe"; "$S/bench_old/target/release/bench.exe"

